import type { Metadata } from 'next'
import { notFound } from 'next/navigation'

import {
  getBlogComments,
  getBlogPost,
  getBlogPosts,
} from '@/lib/json-placeholder'

import { BackButton } from './back-button'

interface BlogPostPageProps {
  params: Promise<{ id: string }>
}

export const dynamicParams = true

export async function generateStaticParams(): Promise<Array<{ id: string }>> {
  const posts = await getBlogPosts({ revalidate: 300 })

  return posts.slice(0, 10).map((post) => ({
    id: String(post.id),
  }))
}

export async function generateMetadata({
  params,
}: BlogPostPageProps): Promise<Metadata> {
  const { id } = await params
  const post = await getBlogPost(id, { revalidate: 300 })

  if (post === null) {
    notFound()
  }

  const description = post.body.slice(0, 160)

  return {
    title: post.title,
    description,
    openGraph: {
      title: post.title,
      description,
    },
  }
}

export default async function BlogPostPage({ params }: BlogPostPageProps) {
  const { id } = await params
  const [post, comments] = await Promise.all([
    getBlogPost(id, { revalidate: 300 }),
    getBlogComments(id, { revalidate: 300 }),
  ])

  if (post === null) {
    notFound()
  }

  return (
    <article>
      <BackButton />

      <h1>{post.title}</h1>
      <p>{post.body}</p>

      <h2>Comments ({comments.length})</h2>
      <div className="comments">
        {comments.map((comment) => (
          <div key={comment.id} className="comment">
            <h3>{comment.name}</h3>
            <p>{comment.body}</p>
            <small>By: {comment.email}</small>
          </div>
        ))}
      </div>
    </article>
  )
}
const JSON_PLACEHOLDER_URL = 'https://jsonplaceholder.typicode.com'

export interface BlogPost {
  userId: number
  id: number
  title: string
  body: string
}

export interface BlogComment {
  postId: number
  id: number
  name: string
  email: string
  body: string
}

interface DataRequestOptions {
  cache?: RequestCache
  revalidate?: number | false
}

interface PostsRequestOptions extends DataRequestOptions {
  limit?: number
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === 'object' && value !== null
}

function isBlogPost(value: unknown): value is BlogPost {
  return (
    isRecord(value) &&
    typeof value.userId === 'number' &&
    typeof value.id === 'number' &&
    typeof value.title === 'string' &&
    typeof value.body === 'string'
  )
}

function isBlogComment(value: unknown): value is BlogComment {
  return (
    isRecord(value) &&
    typeof value.postId === 'number' &&
    typeof value.id === 'number' &&
    typeof value.name === 'string' &&
    typeof value.email === 'string' &&
    typeof value.body === 'string'
  )
}

function createRequestInit({
  cache,
  revalidate,
}: DataRequestOptions): RequestInit {
  const requestInit: RequestInit = {}

  if (cache !== undefined) {
    requestInit.cache = cache
  }

  if (revalidate !== undefined) {
    requestInit.next = { revalidate }
  }

  return requestInit
}

async function readJson(response: Response): Promise<unknown> {
  if (!response.ok) {
    throw new Error(
      `JSONPlaceholder request failed with status ${response.status}`
    )
  }

  return response.json() as Promise<unknown>
}

export async function getBlogPosts({
  limit,
  ...requestOptions
}: PostsRequestOptions = {}): Promise<BlogPost[]> {
  const url = new URL('/posts', JSON_PLACEHOLDER_URL)

  if (limit !== undefined) {
    url.searchParams.set('_limit', String(limit))
  }

  const response = await fetch(url, createRequestInit(requestOptions))
  const data = await readJson(response)

  if (!Array.isArray(data) || !data.every(isBlogPost)) {
    throw new Error('JSONPlaceholder returned an invalid posts response')
  }

  return data
}

