  id: string,
  requestOptions: DataRequestOptions = {}
): Promise<BlogPost | null> {
  const response = await fetch(
    `${JSON_PLACEHOLDER_URL}/posts/${encodeURIComponent(id)}`,
    createRequestInit(requestOptions)
  )

  if (response.status === 404) {
    return null
  }

  const data = await readJson(response)
  return isBlogPost(data) ? data : null
}

export async function getBlogComments(
  id: string,
  requestOptions: DataRequestOptions = {}
): Promise<BlogComment[]> {
  const response = await fetch(
    `${JSON_PLACEHOLDER_URL}/posts/${encodeURIComponent(id)}/comments`,
