type Post = {
  id: number
  title: string
  content: string
}

type CreatedPost = Post & {
  createdAt: string
}

type CreatePostBody = Pick<Post, 'title' | 'content'>

type JsonObject = Record<string, unknown>

const posts: Post[] = [
  { id: 1, title: 'First Post', content: 'This is the first post' },
  { id: 2, title: 'Second Post', content: 'This is the second post' },
]

function isJsonObject(value: unknown): value is JsonObject {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function isCreatePostBody(value: unknown): value is CreatePostBody {
  return (
    isJsonObject(value) &&
    typeof value.title === 'string' &&
    value.title.length > 0 &&
    typeof value.content === 'string' &&
    value.content.length > 0
  )
}

async function readJsonBody(request: Request): Promise<unknown> {
  try {
    const body: unknown = await request.json()
    return body
  } catch {
    return null
  }
}

export function GET(): Response {
  return Response.json(posts, { status: 200 })
}

export async function POST(request: Request): Promise<Response> {
  const body = await readJsonBody(request)

  if (!isCreatePostBody(body)) {
    return Response.json(
      { error: 'Title and content are required' },
      { status: 400 }
    )
  }

  const newPost: CreatedPost = {
    id: Date.now(),
    title: body.title,
    content: body.content,
    createdAt: new Date().toISOString(),
  }

  return Response.json(newPost, { status: 201 })
}
type PostRouteContext = {
  params: Promise<{ id: string }>
}

type Post = {
  id: number
  title: string
  content: string
  createdAt: string
}

type UpdatedPost = Omit<Post, 'createdAt'> & {
  updatedAt: string
}

type UpdatePostBody = {
  title?: string
  content?: string
}

type JsonObject = Record<string, unknown>

function isJsonObject(value: unknown): value is JsonObject {
  return typeof value === 'object' && value !== null && !Array.isArray(value)
}

function isUpdatePostBody(value: unknown): value is UpdatePostBody {
  return (
    isJsonObject(value) &&
    (value.title === undefined || typeof value.title === 'string') &&
    (value.content === undefined || typeof value.content === 'string')
  )
}

async function readJsonBody(request: Request): Promise<unknown> {
  try {
    const body: unknown = await request.json()
    return body
  } catch {
    return null
  }
}

export async function GET(
  _request: Request,
  { params }: PostRouteContext
): Promise<Response> {
  const { id } = await params
  const post: Post = {
    id: Number.parseInt(id, 10),
    title: `Post ${id}`,
    content: `This is the content for post ${id}`,
    createdAt: new Date().toISOString(),
  }

  return Response.json(post, { status: 200 })
}

export async function PUT(
  request: Request,
  { params }: PostRouteContext
): Promise<Response> {
  const [{ id }, body] = await Promise.all([params, readJsonBody(request)])

  if (!isUpdatePostBody(body)) {
    return Response.json(
      { error: 'Title and content must be strings when provided' },
      { status: 400 }
    )
  }

  const updatedPost: UpdatedPost = {
    id: Number.parseInt(id, 10),
    title: body.title || `Post ${id}`,
    content: body.content || `Updated content for post ${id}`,
    updatedAt: new Date().toISOString(),
  }

  return Response.json(updatedPost, { status: 200 })
}

export async function DELETE(
  _request: Request,
  { params }: PostRouteContext
): Promise<Response> {
  const { id } = await params

  return Response.json(
    { message: `Post ${id} deleted successfully` },
    { status: 200 }
  )
}

